# owner: platform
"""Seating charts built from a roster."""

from typing import List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _name(pupil: Student) -> str:
    return f"{pupil.last_name}, {pupil.first_name}"


# ---
def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    if per_row < 1 or not students:
        raise ProjectError("need students and seats")
    names = sorted(map(_name, students))
    rows = [
        names[start:start + per_row]
        for start in range(0, len(names), per_row)
    ]
    return [
        f"Row {num}: " + " | ".join(row)
        for num, row in enumerate(rows, 1)
    ]

