# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _pupil(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split(self):
        pupils = [
            _pupil("Halloway", "Juno"),
            _pupil("Dunmere", "Piet"),
            _pupil("Zane", "Omar"),
        ]
        self.assertEqual(
            seating_rows(pupils, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Omar",
            ],
        )

    def test_bad_seat_count(self):
        pupils = [_pupil("Zane", "Omar")]
        for count in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(pupils, count)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
